Method.Implementation:
	$$$TRACE( "MergeX12 for: " _ trigStr)
	set prevX12Rec = ##class(IHC.ITF.DStruc.DndCoreEraX12Record).%New()
	#dim interchange As %ArrayOfDataTypes

	// Will store Interchange and group information for the first X12 for a receiver
	set interchange = ##class(%ArrayOfDataTypes).%New()
	set group  = ##class(%ArrayOfDataTypes).%New()

	// ST records of all X12 nessages for a receiver
	set ST  = ##class(%ArrayOfDataTypes).%New()

	set tpInfo = ""
	set reply = ""
	// End of Record will have timestamp (TriggerTime) of the batch as CKPYREFID
	// Process all records for the triggerTime
	#dim rs As %SQL.StatementResult
		Set rs = ##class(%SQL.Statement).%ExecDirect(,"SELECT x.ID FROM IHC_ITF_DStruc.DndCoreEraX12Record x, IHC_ITF_DStruc.DndCoreEraRecord r " _
                 " where x.status = 'InProcess' and x.CKPYREFID = r.CKPYREFID " _
                 " and TriggerTime = '" _ trigStr _ "' order by ReceiverId")

		While rs.%Next() {

			set id = rs.%Get("ID")
			set x12Rec = ##class(IHC.ITF.DStruc.DndCoreEraX12Record).%OpenId(id)

			if ($IsObject(x12Rec))
			{
				$$$TRACE( " -- ReceiverId: " _x12Rec.ReceiverId _", Prev ReceiverId: " _ prevX12Rec.ReceiverId) 
				if ( x12Rec.ReceiverId '= prevX12Rec.ReceiverId)
				{	
					$$$TRACE( "New ReceiverId: " _x12Rec.ReceiverId _", " _ x12Rec.CKPYREFID)

					if (prevX12Rec.ReceiverId '= "") // Not First record
					{
						Do ..MergeSTs(prevX12Rec, interchange, group , ST, tpInfo)
					}

					Do interchange.Clear()
					Do group.Clear()
					Do ST.Clear()

					// Get Merge option for the TP
					set tpInfo = ..GetTpLinkInfo(x12Rec.ReceiverId)
					if (tpInfo [ "Batched")
					{	
						if ( $$$ISOK(..ValidateX12(x12Rec.X12stream, tpInfo, .source, .reply)))
						{	
							DO ..GetISA(source, interchange)				
							DO ..GetGS(source, group)					
							Do ..GetST(source, ST)
						}
						else
						{
							set x12Rec.Status = "ValidationFailed-Processed-Batched"

							if ($IsObject(reply))
							{
								set x12Rec.X12Replystream = reply
							}
							else
							{
								$$$LOGERROR("X12 reply is not a stream object")
							}
							set stat = x12Rec.%Save()
							if ($$$ISERR(stat))
							{
								$$$LOGERROR("X12 reply save: " _ $SYSTEM.Status.GetErrorText(stat))
							}

							continue
						}
					}
					else
					{

						if ( $$$ISOK(..ValidateX12(x12Rec.X12stream, tpInfo, .source, .reply)))
						{
							DO ..GetISA(source, interchange)
						}
						else
						{
							set x12Rec.Status = "ValidationFailed-Processed-Single"

							if ($IsObject(reply))
							{
								set x12Rec.X12Replystream = reply
							}
							else
							{
								$$$LOGERROR("X12 reply is not a stream object")
							}
							set stat = x12Rec.%Save()
							if ($$$ISERR(stat))
							{
								$$$LOGERROR("X12 reply save: " _ $SYSTEM.Status.GetErrorText(stat))
							}
						}

					}

				}
				elseif (tpInfo [ "Batched")
				{
					if (prevX12Rec.Status = "InProcess")
					{
						set prevX12Rec.Status = "Merged"
						Do prevX12Rec.%Save()
					}

					$$$TRACE( " - Repeat ReceiverId: " _ x12Rec.ReceiverId _", CKPYREFID: " _ x12Rec.CKPYREFID _", size: " _ x12Rec.X12stream.Size)
					if ( $$$ISOK(..ValidateX12(x12Rec.X12stream, tpInfo, .source, .reply)))
					{
						// DO ..ParseX12(x12Rec.X12stream, .source)
						Do ..GetST(source, ST)
						set x12Rec.Status = "Merged"
						Do x12Rec.%Save()
					}
					else
					{
						set x12Rec.Status = "ValidationFailed-Processed-Batched"

						if ($IsObject(reply))
						{
							set x12Rec.X12Replystream = reply
						}
						else
						{
							$$$LOGERROR("X12 reply is not an object")
						}
						set stat = x12Rec.%Save()
						if ($$$ISERR(stat))
						{
								$$$LOGERROR("X12 reply save: " _ $SYSTEM.Status.GetErrorText(stat))
						}

					}
				}
				else
				{

					$$$TRACE("Repeat TP, not batched, tpInfo: " _ tpInfo) // Is not a batch - Get ISA values

					Do ..MergeSTs(prevX12Rec, interchange, group , ST, tpInfo )
					Do interchange.Clear()
					Do group.Clear()
					Do ST.Clear()
					set tpInfo = ..GetTpLinkInfo(x12Rec.ReceiverId)
					if ( $$$ISOK(..ValidateX12(x12Rec.X12stream, tpInfo, .source, .reply)))
					{
						// DO ..ParseX12(x12Rec.X12stream, .source)
						DO ..GetISA(source, interchange)
					}
					else
					{
						set x12Rec.Status = "ValidationFailed-Processed-Single"
						if ($IsObject(reply))
						{
							set x12Rec.X12Replystream = reply
						}
						else
						{
							$$$LOGERROR("X12 reply is not an object")
						}
						set stat = x12Rec.%Save()
						if ($$$ISERR(stat))
						{
							$$$LOGERROR("X12 reply save: " _ $SYSTEM.Status.GetErrorText(stat))
						}

					}

				}
				set prevX12Rec = x12Rec

			}
			else
			{
				$$$TRACE( id _ "- Not an object")
			}
		}
		if (interchange.Count() > 1)
		{
			// Last Record
			Do ..MergeSTs(prevX12Rec, interchange, group , ST, tpInfo )
		}
		$$$TRACE("--- Merging process complete for IHC_ITF_DStruc.DndCoreEraX12Record ---")

set tSC = $$$OK	
set snipLevel = $PIECE(tpInfo, "#", 3)

// $$$TRACE( " X12 Validation, Stream length:" _ X12stream.Size)

set pDocIn = ##class(EnsLib.EDI.X12.Document).%New()
set pDocIn = pDocIn.ImportFromLibraryStream(X12stream, .tSC)

if ($$$ISOK(tSC))
{

	if (pDocIn.DocType = "")
	{
	   set pDocIn.DocType = "HIPAA_5010:Interchange:Group" 
	}

	if (pDocIn.%Extends("EnsLib.EDI.X12.Document"))
	{
		set tSC = ##class(Ens.X12.FunctionSet).X12ValidateDocument(pDocIn, "SNIP", snipLevel)

		if ($$$ISERR(tSC))
		{
			$$$LOGERROR( " -*- X12 Validation failed, " _ tpInfo _ ", RawContent length: " _ $L(pDocIn.RawContent))
			#dim replyDoc as EnsLib.EDI.X12.Document
			set replyDoc = ##class(Ens.X12.FunctionSet).X12BatchReply(pDocIn, "All", "SNIP", snipLevel, "All") 
			  if ($IsObject(replyDoc))
			  {
			  	  set reply = ##class(%Stream.GlobalCharacter).%New()
				  set oStat = replyDoc.OutputToLibraryStream(reply)

				  $$$TRACE("X12BatchReply stream size: " _  reply.Size _ ", OutToStream: " _ oStat)

			  }
			  // TBD - Store in long term storage, start SH workflow

		}
		else
		{
			// $$$TRACE( " X12 Validation passed")
			SET source = pDocIn
		}
	}
}
return tSC

	#dim source As EnsLib.EDI.X12.Document

	// $$$TRACE( "Stream length: " _ fileStream.Size)

	set x12Data = ""
	do
	{
		set len = 32000
		set x12Data = x12Data _ fileStream.Read(.len, .sc)

	} while(len >= 0 && sc = 1)


    Try {
		set source = ##class(EnsLib.EDI.X12.Document).ImportFromString(x12Data)
		 }
	 Catch thrownErr {
		If $ZE="" {
			Set tSC=thrownErr.AsStatus()
			$$$LOGERROR( "Error: " _ tSC)
		} Else {
			Set tSC=##class(Ens.Util.Error).EnsSystemError($classname(),"Transform")
			$$$LOGERROR(  "System Error: " _ tSC)
		}
	}


    Try {

		 if ( ($ISOBJECT(source)) && (source.%Extends("EnsLib.EDI.X12.Document")) )
		 {

				Set tBlankSrc=1, source.DocType="HIPAA_5010:Interchange:Group" 

			// $$$TRACE("ISA - IDs: " _ source.GetValueAt("ISA:InterchangeReceiverId")   _" -> " _ source.GetValueAt("ISA:InterchangeReceiverID"))


			// WRITE !, source.Name _" # of Children " _ source.ChildCount  _" # of segments: " _ source.SegCountGet() 
			#dim seg As EnsLib.EDI.X12.Segment 

			for segNum=1:1:source.SegCountGet()
			{

				set seg = source.GetSegmentAt(segNum)
				set segPath = source.GetSegmentPath(segNum, .segStat)

				set stat = seg.GetContentArray(.pContents,"source", "HIPAA_5010:" _ seg.Name)
				if $$$ISERR(stat)
				{
					$$$TRACE( "Error in GetContentArray: " _ stat)
					return
				}
				if (segPath [ "ISA")
				{		
					Do interchange.SetAt(seg, 1)
				}
				elseif (segPath [ "IEA")
				{		
					Do interchange.SetAt(seg, 2)
				}

			}
		 }
	 }
	 Catch thrownErr {
		If $ZE="" {
			Set tSC=thrownErr.AsStatus()
			$$$LOGERROR( "GetISA Error: " _ tSC)
		} Else {
			Set tSC=##class(Ens.Util.Error).EnsSystemError($classname(),"Transform")
			$$$LOGERROR( "GetISA System Error: " _ tSC)
		}
	}

	Set k1="",tSC=1

	if ( ($ISOBJECT(source)) && (source.%Extends("EnsLib.EDI.X12.Document")) )
	{
		Do
		{	
			Set tBlankSrc=1, source.DocType="HIPAA_5010:Interchange:Group" 				

			Set k1=source.NextChild(k1,source.GetSegmentIndex("GroupDocsRef",.tSCTrans))
			if ('$IsObject(k1))
			{
				// WRITE !, "-- No more FunctionalGroups --"

				QUIT
			}
			Set source.FunctionalGroups(k1)=k1
			If ""=k1.DocType {
				Set tDocType = k1.resolveChildDocType()
				Set tSC =k1.PokeDocType(tDocType)
			}
			Set tSC =source.FunctionalGroups(k1).BuildMap()
			if $$$ISERR(tSC)
			{
				$$$TRACE( "FunctionalGroups BuildMap: " _ tSC)
				return
			}
			#dim gsSeg As EnsLib.EDI.X12.Segment 						
			For si=1:1:source.FunctionalGroups(k1).SegCount 
	        {
		        set gsSeg = source.FunctionalGroups(k1).GetSegmentAt(si)
				set gsSegPath = source.FunctionalGroups(k1).GetSegmentPath(si, .gsSegStat)

				// WRITE !, gsSeg.OutputToString() _" -->" _ gsSeg.DocType
				if (gsSegPath [ "GS") 
				{

					Do group.SetAt(gsSeg, 1)
				}
				elseif (gsSegPath [ "GE")
				{
					set sg2 = gsSeg.%ConstructClone(1)
					Do sg2.SetValueAt("x", "1","set","")
					Do group.SetAt(sg2, 2)

					// WRITE !, sg2.DocType _": " _ sg2.OutputToString()
				}			 

        	}
		}while ($IsObject(k1))
	}

	Set k1="",tSC=1
	set source.DocType="HIPAA_5010:Interchange:Group"

	For {
		Set k1=source.NextChild(k1,source.GetSegmentIndex("GroupDocsRef",.tSCTrans))
		if ('$IsObject(k1))
		{
			// WRITE !, "-- No more FunctionalGroups --"

			QUIT
		}
		Set source.FunctionalGroups(k1)=k1
		If ""=k1.DocType {
			Set tDocType = k1.resolveChildDocType()
			Set tSC =k1.PokeDocType(tDocType)
		}
		Set tSC =source.FunctionalGroups(k1).BuildMap()
		if $$$ISERR(tSC)
		{
			$$$TRACE( "FunctionalGroups BuildMap: " _ tSC)
			return
		}


		For i=1:1:source.FunctionalGroups(k1).ChildCount
        { 
          #dim individualST As EnsLib.EDI.X12.Document
          set individualST = source.FunctionalGroups(k1).getNthChild(i,2)
          If ""=individualST.DocType {
			Set tDocType = individualST.resolveChildDocType()
			Set tSC =individualST.PokeDocType(tDocType)
		 }
		 Set tSC =individualST.BuildMap()
		if $$$ISERR(tSC)
		{
			$$$TRACE( "FunctionalGroups BuildMap: " _ tSC)
			return
		}

           // WRITE !, i _". " _ individualST.DocType // _ "= " _ individualST.OutputToString()


	        set refGroupIDind=individualST.GetSegmentIndex("TRN",.refGroupIDstatus)  
	        set GroupID=individualST.GetValueAt(refGroupIDind_":2")
	        set stCtrlNum = individualST.GetValueAt("1:2")

	        set st2 = individualST.%ConstructClone(1)

	        $$$TRACE("   ST: " _ stCtrlNum _ ": " _ GroupID _", count: " _ individualST.SegCount _", size: " _ individualST.FullSize _ ", ST2 size: " _ st2.FullSize)

	        Do ST.SetAt(st2 , GroupID)

        }  
	}

if (interchange.Count() > 1)
{
	#dim isaDoc As EnsLib.EDI.X12.Segment
	set isaDoc = interchange.GetAt(1)
	set tSC = isaDoc.DocTypeSet("HIPAA_5010:ISA")
	set isaUniqId = $ZSTRIP(isaDoc.GetValueAt("InterchangeSenderId"), "*W")   _"-" _ $ZSTRIP(isaDoc.GetValueAt("InterchangeReceiverID"), "*W")  _"-" _ $ZSTRIP(isaDoc.GetValueAt("InterchangeControlNumber"), "*W")

	if (ST.Count() > 1)
	{

		$$$TRACE(x12Rec.CKPYREFID _", " _ isaUniqId _ " ---> Merge: " _ ST.Count() _" STs")
		#dim X12stream As %Stream.GlobalCharacter
		set X12stream = ##class(%Stream.GlobalCharacter).%New()
		Do X12stream.Write(isaDoc.OutputToString())
		Do X12stream.Write(group.GetAt(1).OutputToString())
		set st = ""
		for i=1:1:ST.Count()
		{
			#dim str As EnsLib.EDI.X12.Document
			set str = ST.GetNext(.st)


			set stat = str.SetValueAt("000"_i, "1:2" ,"set","")
			// WRITE !, "Set ST control number: " _ stat _ ", ST size: " _ str.FullSize)
			// $$$TRACE( "New ST control number: " _ str.GetValueAt("1:2"))  
			Do X12stream.Write(str.OutputToString())
		}
		//# Copy GS(1): Number of Transaction Sets
		Do group.GetAt(2).SetValueAt(ST.Count(),"1")
		Do X12stream.Write(group.GetAt(2).OutputToString())
		Do X12stream.Write(interchange.GetAt(2).OutputToString())

		$$$TRACE(isaUniqId _", --- Merged Stream size: " _ X12stream.Size)

		set newX12Rec = ##class(IHC.ITF.DStruc.DndCoreEraX12Record).%New()
		set newX12Rec.Status = "Processed-Batched"
		set newX12Rec.X12stream = X12stream
		set newX12Rec.ReceiverId= x12Rec.ReceiverId
		set newX12Rec.CKPYREFID = x12Rec.CKPYREFID
		set newX12Rec.CreateTime = $ZDATETIME($HOROLOG,3, 1)
		set newX12Rec.Route = $PIECE(tpInfo, "#", 1)
		set newX12Rec.TpLinkId = $PIECE(tpInfo, "#", 2)
		set newX12Rec.SNIP = $PIECE(tpInfo, "#", 3)
		set newX12Rec.IsaUniqId = isaUniqId
		Do newX12Rec.%Save()
		set x12Rec.Status = "Merged" // Original X12 is marked merged
	}
	else
	{
		$$$TRACE(isaUniqId _ " ---> Single" )
		set x12Rec.Status = "Processed-Single"
		set x12Rec.Route = $PIECE(tpInfo, "#", 1)
		set x12Rec.TpLinkId = $PIECE(tpInfo, "#", 2)
		set x12Rec.SNIP = $PIECE(tpInfo, "#", 3)
		set x12Rec.IsaUniqId = isaUniqId
	}
	if (x12Rec.CKPYREFID '= "")
	{
		Do x12Rec.%Save()
	}
}

	set retStr = ""
	 Set rs = ##class(%SQL.Statement).%ExecDirect(,"SELECT lnk.ID, lnk.NAME, lnk.SNIP " _
 "FROM IHC_ITF_ITFCOMMON_TPManage.TRADELINKS lnk, IHC_ITF_ITFCOMMON_TPManage.TPIDS tp, IHC_ITF_ITFCOMMON_TPManage.TRANSACTIONTYPES tt " _
 "where tp.ID = lnk.IsaReceiverId and tt.TransactionSetId = '835' AND tt.ID = lnk.TRANSTYPE " _
 "AND tp.TPID = '" _ tpId _ "' " )

	While rs.%Next() {
		set nm = rs.%Get("NAME")
		set id = rs.%Get("ID")
		// $$$TRACE("TP Link: " _ nm _", Id: " _ id)	

		Set tpLink = ##class(IHC.ITF.ITFCOMMON.TPManage.TRADELINKS).%OpenId(id)
		if ($IsObject(tpLink))
		{
		 set retStr = tpLink.Routing _ "#" _id _"#" _ rs.%Get("SNIP")


		 Set tSet="",tId=""
			For {
				Set tSet = tpLink.customProp.GetNext(.tId)
				Quit:""=tId
				if (tSet.Key = "BatchingMode835")
				{
					set retStr = retStr _ "#" _tSet.Value

					QUIT
				}
			}

		}
		else
		{
		 WRITE !, "Not an object"
		}
	}
	$$$TRACE("TP Link for " _ tpId _ ": " _ ", Return: " _ retStr)
	return retStr
